/* ================= MCQ QUESTIONS - Control Survey - Unit 2: Levelling =================
 * One unit per file: the app loads ONLY this unit's 3 files (mcq + subjective
 * + study) when you open the unit - see js/data-manifest.js.
 * ============================================================================== */
window.EXTRA = window.EXTRA || {};

window.EXTRA["Levelling"] = window.EXTRA["Levelling"] || {};
window.EXTRA["Levelling"].mcq = [
      {q:"Levelling is the process of determining:", o:["Areas of parcels", "Horizontal distances", "Relative heights or elevations of points", "Horizontal angles"], a:2, e:"Levelling determines the difference of elevation between points, and from a known datum (mean sea level) the reduced level (RL) of each point. Measuring horizontal distances and angles is the job of chain surveying, theodolite traversing and tacheometry - not levelling."},
      {q:"The reading taken on a point of known elevation is called the:", o:["Intermediate sight", "Change point", "Fore sight", "Back sight"], a:3, e:"A back sight (BS) is the first reading after setting up the instrument, taken on a point whose RL is already known (a bench mark or a change point). It is added to the RL to get the height of instrument: HI = RL of BM + BS. An intermediate sight and a fore sight are taken on points whose elevation is not yet known."},
      {q:"A fixed point of known elevation above a datum is called a:", o:["Bench mark", "Turning point", "Station", "Change point"], a:0, e:"A bench mark (BM) is a permanent, well-defined point whose reduced level is known with respect to the datum; it is the starting point or the closing point of levelling work. Turning point (change point) and station carry no information about a known elevation."},
      {q:"In the rise and fall method, the arithmetic check is:", o:["Number of stations = number of readings", "Sum of BS - sum of FS = sum of rise - sum of fall = last RL - first RL", "Sum of BS = sum of FS", "Sum of all RL = 0"], a:1, e:"The rise and fall method has three checks that must all agree: sum of BS - sum of FS = sum of rises - sum of falls = last RL - first RL. It also gives a check on every intermediate sight (each reading is compared with the previous one), which is why it is preferred for precise work even though it is slower than the height of instrument method."},
      {q:"A point on which both a fore sight and a back sight are taken is called a:", o:["Station", "Bench mark", "Change point", "Datum"], a:2, e:"A change point (turning point) is the point where the levelling is carried forward: a fore sight is taken on it before shifting the instrument and a back sight after shifting. It must be a firm, stable point (a rock, a peg or a staff plate) because if it sinks between the two readings a systematic error enters the whole line. The instrument is set up midway between the two staffs to cancel collimation, curvature and refraction errors."},
      {q:"The elevation of a point above mean sea level is called its:", o:["Reduced level", "Back sight", "Fore sight", "Height of instrument"], a:0, e:"Reduced level (RL) is the height of a point above the datum, normally mean sea level. All staff readings reduce to RLs through the two relations of levelling: HI = RL + BS, and RL = HI - (IS or FS)."},
      {q:"The height of the line of collimation above the datum is called the:", o:["Height of instrument", "Bench mark", "Change point", "Reduced level"], a:0, e:"Height of instrument (HI) is the elevation of the horizontal plane of collimation (the line of sight) above the datum, not the height of the instrument itself on its tripod: HI = RL of the point + back sight. Every unknown RL at that set-up is then HI - staff reading (IS or FS)."},
      {q:"In levelling, the first reading taken on a change point is the:", o:["Intermediate sight", "Fore sight", "Zero reading", "Back sight"], a:1, e:"At a change point the fore sight is read first (before the instrument is shifted) and the back sight afterwards (from the new set-up). A zero reading is not a levelling term; readings are counted from the foot of the staff, which is the point of contact with the ground."},
      {q:"The arithmetic check for the height of instrument method is:", o:["Number of BS equals number of FS", "Sum of BS - sum of FS = last RL - first RL", "Sum of BS + sum of FS = sum of IS", "Sum of rise = sum of fall always"], a:1, e:"In the height of instrument method the only arithmetic check is sum of BS - sum of FS = last RL - first RL. It checks the arithmetic of the reduction but not the individual intermediate sights; the rise and fall method gives that additional check on every sight."},
      {q:"The surface of still water is an example of a:", o:["Vertical plane", "Steep slope", "Level surface", "Horizontal line"], a:2, e:"A level surface is a curved surface everywhere perpendicular to the direction of gravity; still water takes this shape (it follows the curvature of the earth, so a line of sight over a long distance runs above it). A truly horizontal line, in contrast, is a straight line perpendicular to the plumb line at a single point."},
      {q:"Profile levelling is carried out to:", o:["Test instruments", "Fix property corners", "Find elevations along a centre line such as a road", "Measure bearings"], a:2, e:"Profile (longitudinal) levelling gives the ground profile along a centre line - used for the gradient and earthwork of roads, canals, railways and pipelines. Cross-sectioning gives levels at right angles to the centre line; together they are used to compute cutting and filling. Fixing property corners and measuring bearings belong to cadastral/traverse work."},
      {q:"Reciprocal levelling is used to:", o:["Train beginners", "Speed up the work", "Double the staff length", "Eliminate collimation and curvature errors across wide gaps"], a:3, e:"When a river, valley or deep gorge makes it impossible to set up midway between the two staffs, two set-ups are taken - one on each bank - and the readings are averaged. The collimation and curvature errors act in opposite senses in the two observations and cancel, giving the true difference of level; the refraction error, however, is not completely eliminated because the atmosphere is not uniform along the line."},
      {q:"Contours of different elevations:", o:["Always cross in valleys", "Meet at every summit", "Are always circular", "Never cross except at an overhanging cliff"], a:3, e:"A contour is a line joining points of equal elevation; since one point cannot have two elevations, contours of different values cannot cross each other - the only exception being an overhanging cliff or a cave, where the surface is not single-valued. Contours close on themselves (inside or outside the map), crowd together on steep ground and are widely spaced on flat ground."},
      {q:"Cross hairs can be seen in which part of the dumpy level?", o:["diaphragm", "optical plummet", "display window", "objective glass"], a:0, e:"The cross hairs (reticule) are etched on a glass diaphragm fixed in the telescope in the plane where the image of the object is formed, i.e. in the plane of the cross-wire. The objective forms the image, the eyepiece magnifies it, and the optical plummet (where fitted) is only for centring the instrument over the station."},
      {q:"What will be the correction for curvature for a distance of 1000 m?", o:["0.0673 m", "0.0785 m", "78.50 m", "6.73 m"], a:1, e:"Curvature correction Cc = 0.0785 D squared, where D is in kilometres. For D = 1 km: Cc = 0.0785 x 1 squared = 0.0785 m. The correction is subtractive (it makes the staff reading too large). The refraction correction is 0.0112 D squared, and the combined correction (curvature minus refraction) is 0.0673 D squared, so 0.0673 m is the extra distractor here."},
      {q:"The reading on a 4.0 m staff at a point is observed as 2.895 m. If the staff was 8 cm out of the plumb line, the correct reading should have been:", o:["2.8938 m", "2.8150 m", "2.8961 m", "2.8950 m"], a:0, e:"An inclined staff always gives a reading larger than the true one; the error is the difference between the slope distance and its vertical projection. Correct reading = square root of (2.895 squared - 0.08 squared) = 2.8938 m, i.e. the error is about 1.1 mm for an 8 cm out-of-plumb staff at this reading. This is why the staff must be held truly vertical, supported by a staff bubble or a plumb line in precise work."},
      {q:"A back sight on a bench mark of R.L. 100.000 m was 3.250 m. The staff was then held inverted to the soffit (bottom face) of a girder and the reading was 1.250 m. The R.L. of the soffit of the girder is:", o:["101.250 m", "102.000 m", "104.500 m", "103.250 m"], a:2, e:"HI = 100.000 + 3.250 = 103.250 m. For an inverted staff the point read is above the line of sight, so its reading is added (and booked as a minus/negative sight): RL = HI + inverted reading = 103.250 + 1.250 = 104.500 m."},
      {q:"The sensitivity of a bubble tube is 20 seconds. A staff is held at a distance of 200 m. What is the error in reading it if the bubble is out by one division?", o:["0.704 m", "0.0704 m", "0.0194 m", "0.1940 m"], a:2, e:"Error = (sensitivity in seconds x distance) / 206265 = (20 x 200) / 206265 = 0.0194 m. The factor 206265 is the number of seconds in one radian, so the formula converts the angular tilt of the line of sight into a linear error on the staff. The error grows in direct proportion to the sight distance, which is one reason for keeping sights short in precise levelling."},
      {q:"A level set up 25 m from peg A and 50 m from peg B reads 2.847 m on the staff at A and 3.462 m at B, with the bubble central. The reduced levels of A and B are 283.665 m and 284.295 m. The collimation error per 100 m of sight is:", o:["0.015 m", "0.030 m", "0.045 m", "0.060 m"], a:3, e:"Observed difference of level = 3.462 - 2.847 = 0.615 m; true difference = 284.295 - 283.665 = 0.630 m. So the sight error over the 25 m difference of the two sight lengths is 0.630 - 0.615 = 0.015 m, i.e. 0.015 / 25 = 0.0006 m per metre of sight. Per 100 m: 0.0006 x 100 = 0.060 m. (0.015 m is the error over the 25 m difference of sight lengths, and 0.045 m the error over the 75 m of total sight length - the two classic distractors.)"},
      {q:"Levelling deals with measurement in:", o:["horizontal plane", "vertical plane", "both horizontal and vertical planes", "inclined plane"], a:1, e:"Levelling is concerned with measurement in the vertical plane - vertical distances (heights) and the tilts or gradients of lines. Horizontal distances and horizontal angles are measured in chain surveying, traversing and tacheometry."},
      {q:"The datum adopted in India is the mean sea level at:", o:["Kolkata", "Chennai", "Mumbai", "Karachi"], a:2, e:"The Survey of India adopted the mean sea level at Mumbai (Bombay) as the national vertical datum. Karachi was the datum used before independence, and it is now the datum of Pakistan - the two are the classic distractors."},
      {q:"Height of instrument may be defined as:", o:["height of the instrument at the time of observation", "the elevation of the plane of collimation, when the instrument is accurately levelled", "height of instrument, if the backsight distance is equal to the foresight distance", "height of staff"], a:1, e:"Height of instrument is the elevation of the horizontal plane of collimation (line of sight) with respect to the datum - not the physical height of the instrument above the ground. HI = RL of the point + back sight; unknown reduced levels are then HI minus the intermediate or fore sight."},
      {q:"In an external focussing telescope, the focussing of the objective is achieved by:", o:["movement of a negative concave lens", "by movement of objective", "Both (a) and (b)", "double convex lens"], a:1, e:"In an external focusing telescope the objective itself is moved forward or backward inside the tube to bring the image into the plane of the cross-wire. In an internal focusing telescope, by contrast, a small concave (negative) lens inside the tube is moved while the objective stays fixed - option (a) describes that type. Internal focusing is now the standard because the tube length does not change and the instrument stays better balanced."},
      {q:"Line of collimation is defined as the:", o:["line joining the intersection of cross-hair, optical centre of objective and its continuation when the bubble is central", "Line joining the centre of eyepiece and optical centre of objective", "line tangential to the longitudinal curve of the bubble tube at its mid-point", "inclined line of sight"], a:0, e:"The line of collimation is the line joining the intersection of the cross hairs with the optical centre of the objective, and its continuation, when the bubble is central. When the bubble is central, this line should be exactly horizontal - that is the whole basis of spirit levelling. Option (c) defines the axis of the bubble tube, and option (b) is only an approximation of the line of sight inside the telescope."},
      {q:"Pick out the correct statement.", o:["Height of instrument method is better as compared to the rise and fall method.", "The length of a metric staff used in levelling is 2.0 m.", "The rise and fall method for the reduction of levels provides checks on all sights.", "The effect of curvature is to cause the objects sighted to appear higher than they really are."], a:2, e:"The rise and fall method compares every consecutive pair of readings, so it checks the intermediate sights as well - that is its advantage, and the reason it is preferred for precise work. The height of instrument method gives no check on intermediate sights. Metric levelling staffs are commonly 3 m, 4 m or 5 m long (2.0 m is not standard), and curvature makes objects appear lower, not higher, than they are."},
      {q:"Choose the correct statement.", o:["In levelling, if back sight is less than fore sight, the back sight station is lower than the fore sight station.", "In reciprocal levelling, the error due to refraction is eliminated.", "At a change point in levelling, two back sights are taken.", "The effect of curvature is to cause the objects sighted to appear lower than they really are."], a:3, e:"Curvature makes the staff appear lower, so the reading is too large - the correction is subtractive. A back sight smaller than the fore sight means a fall, i.e. the forward station is lower, not the back station. At a change point one fore sight and one back sight are taken (not two back sights), and in reciprocal levelling refraction is reduced but not completely eliminated because it depends on variable atmospheric conditions."},
      {q:"Choose the correct statement.", o:["The nature of combined correction due to curvature and refraction is additive.", "The figures on the staff are very distinct if the staff is kept near the level.", "In levelling, if the previous reading is less than the next consecutive reading, it indicates a rise.", "The effect of curvature and refraction can be neglected, if the instrument is kept mid-way."], a:3, e:"When the instrument is set up midway between the two staffs, the two sights are of equal length, so curvature and refraction affect both readings equally and cancel out; the same equalization also cancels the collimation error. This is the golden rule of levelling. Curvature and refraction act in opposite senses (the combined correction is not simply additive), and a reading that is larger than the previous one indicates a fall, not a rise."},
      {q:"Choose the correct statement.", o:["The sensitivity of a bubble tube increases with the increase of radius of curvature of the bubble tube.", "The sensitivity of a bubble tube increases with the increase in the length of the vapour bubble.", "The sensitivity of a bubble tube will be more if the diameter of the bubble tube is more.", "All of the above."], a:3, e:"The sensitivity of a level tube is the angle subtended at the centre of the tube by one division of the tube: the smaller that angle, the more sensitive the tube. It therefore increases with a longer radius of curvature (a flatter bore), with a longer bubble and with a larger internal diameter of the tube, and it decreases with a rise in temperature (the liquid expands, the bubble shortens) and with a more viscous liquid."},
      {q:"To calculate the amount of cut and fill:", o:["only profile levelling is sufficient", "only cross sectioning is required", "both profile levelling and cross sectioning are required", "barometric levelling is required"], a:2, e:"Cut and fill (earthwork) volumes are computed from the ground profile along the centre line (longitudinal section) together with cross sections at regular intervals, both compared with the formation level of the design. Profile levelling alone gives only the longitudinal ground line, and cross sectioning alone gives no continuity along the line; barometric levelling is far too rough for earthwork."},
      {q:"The diaphragm of a surveying telescope is held:", o:["inside the eyepiece", "inside the objective", "Either (a) or (b)", "inside the telescope near the eyepiece"], a:3, e:"The diaphragm (reticule plate) is fixed inside the telescope tube in the plane where the objective forms the image, i.e. close to the eyepiece. It is not part of the eyepiece or of the objective itself, so options (a) and (b) are wrong."},
      {q:"In reciprocal levelling with one level machine the error(s) which is NOT completely eliminated is due to:", o:["curvature", "refraction", "non-adjustment of line of collimation", "both (a) and (b)"], a:1, e:"Taking the mean of the two observations (one from each bank) cancels the collimation error and the curvature error, because both act in opposite senses in the two set-ups. The refraction error is only partly eliminated: the density and temperature of the air along a long line across water change from hour to hour, so the two lines of sight are not bent by equal amounts. The standard remedy is to keep the line of sight at least 1 m above the water surface and to observe in calm conditions or at night."},
      {q:"The real image of an object formed by the objective must be:", o:["at the centre of the objective", "at the optical centre of the objective", "in the plane of the cross-wire", "on the staff"], a:2, e:"For a sharp, parallax-free reading the image of the staff must be formed exactly in the plane of the cross-wire, i.e. at the diaphragm. If the image is not in that plane, moving the eye behind the eyepiece makes the cross hairs appear to move over the staff - this is parallax, and it is removed by focusing the eyepiece and then the objective."},
      {q:"Choose the incorrect statement.", o:["Under high temperatures, the liquid in a level tube expands but does not affect the observations made on the staff.", "To minimise error in levelling with an instrument in muddy soils, the fore sights should be taken before back sights on an alternate set up of the instrument.", "In differential levelling, the errors are eliminated completely.", "By keeping the line of sight parallel to the bubble line, the collimation error is eliminated."], a:2, e:"Differential levelling reduces errors but never eliminates them completely: small residual errors remain in the collimation, curvature and refraction, in the staff graduations and in the reading. Option (c) is therefore the incorrect statement, which is what the question asks for. A rise in temperature expands the liquid and shortens the bubble, which reduces the sensitivity of the tube (so the mean RL can still be affected); on soft or muddy ground the staff settles, so on alternate set-ups the fore sight is taken before the back sight so that settling errors tend to cancel; and equalizing the distances of backsight and foresight does eliminate the effect of collimation error."},
      {q:"Choose the correct statement.", o:["Elevation of a point is its vertical coordinate.", "Usually average sea level is considered as datum in levelling.", "Levelling can be used to measure settlement of buildings.", "All of the above."], a:3, e:"All three statements are correct. Elevation (reduced level) is the vertical coordinate (height) of a point with respect to the datum; mean sea level is the usual vertical datum; and repeated precise levelling on fixed points (or the settlement of a structure against a deep bench mark) is the standard method of measuring settlement of buildings, bridges and dams."},
      {q:"Choose the correct statement.", o:["In spirit levelling the vertical angles are also measured.", "Hypsometry is a type of levelling.", "Differential levelling is the most common method of spirit levelling.", "Both (b) and (c)."], a:3, e:"Hypsometry (the measurement of heights, e.g. from the boiling point of water or from maps) is classed as an indirect method of levelling, and differential levelling - the routine method of finding the difference of elevation between distant points through a series of instrument set-ups - is the most common form of spirit levelling. Spirit levelling measures only horizontal lines of sight and vertical staff readings; vertical angles are measured in trigonometrical levelling, not here."},
      {q:"Choose the correct statement.", o:["Fly levelling is a type of spirit levelling.", "Sectioning and cross sectioning are one and the same type of levelling.", "Spot levels are points used to denote instrument position.", "None of the above is correct."], a:0, e:"Fly levelling (a rapid check-run back to the starting bench mark) is a form of spirit levelling. Sectioning and cross sectioning are different: longitudinal sectioning gives the profile along a line, cross sectioning gives levels at right angles to it. Spot levels are individual ground levels taken at scattered points (e.g. for a building site or a contour map), not instrument positions."},
      {q:"The liquid in a level tube should be:", o:["quick acting", "non-freezing", "stable under normal temperature variation", "All of the above"], a:3, e:"The bubble liquid must be quick acting (low viscosity, so the bubble settles quickly and is easy to centre), non-freezing at low temperatures, and stable and non-volatile so that its volume does not change appreciably with normal temperature changes. Alcohol-based liquids with a suitable dye are commonly used for this reason."},
      {q:"Choose the correct statement:", o:["Wye level can be tested rapidly as compared to dumpy level.", "Cooke's level is a combination of good features of dumpy and Wye levels.", "In Cushing's level, the object glass and eyepiece are interchangeable.", "All of the above are correct."], a:3, e:"All three statements are correct. In a Wye level the telescope can be rotated about its own axis in the Y-shaped rests, so the permanent adjustments can be tested quickly (by turning the telescope end for end); Cooke's reversible level combines the good features of the dumpy and Wye types; and in Cushing's level the object glass and the eyepiece can be interchanged to make a long or a short telescope as required."},
      {q:"Choose the incorrect statement.", o:["Hand level can be adjusted and used without a tripod.", "Abney hand level is also known as a clinometer.", "A clinometer can be used as a hand level by setting the pointer to zero.", "In tilting level the telescope can be revolved only about the vertical axis."], a:3, e:"In a tilting level the telescope can be tilted slightly about a horizontal axis with the tilting screw, and it can also be revolved about the vertical axis - that is precisely its advantage: the bubble is brought to the centre at each sight with the tilting screw instead of re-levelling the instrument with the foot screws. The first three statements are all true, so the incorrect statement - the answer required - is (d)."},
      {q:"Choose the correct statement about levelling staffs:", o:["A levelling staff should be held truly vertical on a firm point; otherwise the reading will be too large.", "The telescopic staff commonly used is 4 m long and is graduated in metres, decimetres and centimetres.", "To take a reading on an overhead point (say the soffit of a girder) the staff is held inverted, with its graduated face downwards.", "All of the above are correct."], a:3, e:"All three are correct. An inclined staff always gives a reading larger than the true vertical reading, so a staff with a circular bubble (or a plumb line) is used in precise work; the common telescopic staff is 4 m long in three sliding lengths, graduated in metres, decimetres and centimetres with the zero at the foot; and for an overhead point the staff is inverted so that its graduation zero is against the point, the reading being booked as a minus sight and added to the height of instrument."},
      {q:"Choose the incorrect statement.", o:["Centring is not required in levelling.", "In the two-peg test, the vertical axis is made perpendicular to the plate bubble axis.", "In a tilting level only one permanent adjustment is required.", "In a dumpy level two permanent adjustments are required."], a:1, e:"The two-peg (two-pin) test is the field test of the line of collimation - the error of the line of sight from the horizontal. Making the vertical axis perpendicular to the axis of the plate bubble is a different permanent adjustment (adjustment of the plate levels), so statement (b) confuses the test with another adjustment and is the incorrect statement required. In levelling the instrument need not be centred over a ground point (only levelled), a tilting level needs only the collimation adjustment, and a dumpy level needs two permanent adjustments (plate bubble and line of collimation)."},
      {q:"Choose the correct statement.", o:["By equalising back sight and fore sight distances, the errors due to reading mistakes are eliminated.", "A minus sight is booked for an inverted staff reading.", "Spot levels are determined by sectioning and cross sectioning.", "All of the above."], a:1, e:"Inverted staff readings are booked with a minus sign and are added to (not subtracted from) the height of instrument. Equalizing BS and FS distances removes the instrumental (collimation), curvature and refraction errors - it cannot remove a reading mistake or a booking blunder, which is why the arithmetic check is essential. Spot levels are not obtained from sectioning: they are levels taken at selected scattered points of a site (for example on a grid) to draw spot heights or contours."},
      {q:"Apart from arithmetic, the levelling work is best checked by:", o:["height of instrument method", "rise and fall method", "closed loop check", "open loop check"], a:2, e:"A closed loop (or a run from one bench mark to another of known RL) gives an independent check on the work: the closing error must be within the permissible limit (about 1.1 square root K mm for first-order and 12 to 25 square root K mm for ordinary levelling, K being the length in kilometres). Height of instrument and rise and fall are methods of reduction, not checks on accuracy; an open loop that does not return to a known point cannot reveal the accumulated error."},
      {q:"Choose the correct statement.", o:["The permissible closing error in ordinary levelling is 12 seconds.", "Sectioning does not use the principle of differential levelling.", "Barometric levelling is most suited in flat countries.", "Barometric levelling is performed by altimeters."], a:3, e:"Barometric levelling uses an altimeter (a refined aneroid barometer) to obtain elevations from atmospheric pressure; because 1 mm of mercury corresponds to only about 11 m of height and the pressure changes with the weather, it gives accuracies of the order of 1 m and is used for reconnaissance in hilly or mountainous country - not in flat country. A permissible closing error is expressed in millimetres times the square root of the length in kilometres, not in seconds (seconds are used for angular closing errors in traversing), and sectioning is simply differential levelling along a line."},
      {q:"The sensitiveness of a bubble tube in a level would decrease if:", o:["the radius of curvature of the internal surface of the tube is increased", "the diameter of the tube is increased", "the length of the vapour bubble is increased", "the viscosity of the liquid is increased"], a:3, e:"Sensitivity decreases if the liquid becomes more viscous, because the bubble then moves slowly and sluggishly and its edges are ill-defined. Options (a), (b) and (c) all increase the sensitivity. Sensitivity also decreases when the temperature rises, because the liquid expands and the bubble becomes shorter."},
      {q:"Which one of the following eliminates the error due to curvature and refraction?", o:["Fly levelling", "Levelling by equalising the distances of back sight and fore sight", "Check levelling", "Precise levelling"], a:1, e:"Curvature and refraction depend only on the length of the sight, so if the instrument is set up so that every back sight and fore sight are of equal length, the two errors are equal and opposite in successive readings and cancel out. The same rule cancels the collimation error, which is why the instrument is always kept midway between the two staffs. Fly, check and precise levelling are types of levelling work, not remedies for these errors."},
      {q:"Choose the correct statement(s) about levelling on steep or hilly ground.", o:["Only (i) is correct", "(i) and (ii) are correct", "Only (ii) is correct", "All three are correct"], a:3, e:"Statements: (i) On steep ground the number of instrument set-ups increases, so the work should be checked by closing the loop on a known bench mark and comparing the closing error with the permissible error (a square-root-of-length formula). (ii) A change point must be chosen on a firm, stable object, because if it sinks between the fore sight and the back sight a systematic error enters every subsequent reduced level. (iii) On steep slopes the staff must be held truly vertical (staff bubble or plumb line) because an inclined staff gives too large a reading. All three statements are correct."},
      {q:"Choose the correct statement(s).", o:["Both (i) and (ii) are correct", "Both (ii) and (iii) are correct", "Only (i) is correct", "Only (ii) is correct"], a:0, e:"Statements: (i) Temporary adjustments of a level are made at every instrument set-up in the field (setting up the tripod, levelling the instrument with the foot screws or tilting screw, and focusing the eyepiece and the objective). (ii) Permanent adjustments are made in the workshop by an instrument mechanic, and their object is to establish the fixed relations between the axes of the instrument. So both (i) and (ii) are correct."},
      {q:"Choose the correct statement(s).", o:["Only (i) is correct", "Only (ii) is correct", "Both (i) and (iii) are correct", "All three are correct"], a:2, e:"Statements: (i) Spirit levelling is the most accurate method of determining differences of elevation - true. (ii) Trigonometrical levelling is more accurate than spirit levelling - false: it is quicker over long, broken and steep lines, but its accuracy (of the order of 1 in 5,000 to 1 in 10,000 of the horizontal distance) is lower than that of spirit levelling (of the order of 1 in 50,000 or better). (iii) Barometric levelling is used where rough accuracy (about 1 m) is sufficient, such as reconnaissance in hilly country - true. Hence (i) and (iii) are correct."},
      {q:"The sensitivity of a bubble increases with:", o:["Only (i) is correct", "Only (ii) is correct", "Both (i) and (ii) are correct", "None is correct"], a:2, e:"Statements: (i) The sensitivity of a bubble tube increases with an increase in the radius of curvature of the tube, and (ii) it increases if the internal surface of the tube is finished very smooth, so that the bubble has a sharply defined edge. Both statements are correct. Sensitivity is defined as the angle subtended at the centre of the tube by one division (usually 2 mm) of the tube: alpha = s / R, where s is the length of one division and R the radius of curvature - so the longer the radius and the smoother the bore, the smaller the angle per division and the more sensitive the tube."},
      {q:"In levelling:", o:["Only (i) is correct", "Only (ii) is correct", "Both (i) and (ii) are correct", "(i) follows (ii)"], a:2, e:"Statements: (i) A G.T.S. (great trigonometrical survey) bench mark is fixed with very high precision by the national survey organisation (in Nepal by the Survey Department) and serves as the reference for all other levelling in the area. (ii) A temporary bench mark (T.B.M.) is established by the survey party near the site of the work, and is used only for the duration of that work. Both statements are correct, and they are independent of each other - one does not follow from the other."},
      {q:"Choose the correct statement(s).", o:["Only (i) is correct", "Only (ii) is correct", "Both (i) and (ii) are correct", "None is correct"], a:2, e:"Statements: (i) The curvature of the earth makes the staff appear lower than it really is, so the observed reading is too large and the correction (0.0785 D squared m, D in km) is subtractive. (ii) Refraction bends the line of sight downwards towards the earth, making the staff appear higher, so its correction (0.0112 D squared m) is additive. Both statements are correct; refraction partly counteracts curvature, and the combined correction is 0.0673 D squared m, subtractive."},
      {q:"Levels of the points can be found by:", o:["Only (i) is correct", "Only (ii) is correct", "Both (i) and (ii) are correct", "None is correct"], a:2, e:"Statements: (i) by measuring the atmospheric pressure (barometric levelling, with an altimeter) and (ii) by measuring the boiling point of water (hypsometry), since the boiling temperature falls with increasing height. Both are indirect levelling methods of limited accuracy - several decimetres to about 1 m - and are used where rough heights are adequate, for example in reconnaissance. Both statements are therefore correct."},
      {q:"Reciprocal levelling eliminates the errors due to: (1) curvature of the earth (2) refraction (3) staff graduations (4) non-adjustment of the line of collimation", o:["1, 2 and 3", "1, 3 and 4", "2, 3 and 4", "1, 2 and 4"], a:3, e:"The errors due to curvature (1), refraction (2) and non-adjustment of the line of collimation (4) are the ones dealt with in reciprocal levelling: by observing from both banks and taking the mean, the collimation and curvature errors cancel, and the refraction error is largely - though not completely - cancelled. Staff graduation error (3) is a property of the staff itself and is not removed by reciprocal observation; it is minimised by using a good staff and checking it against a standard."},
      {q:"Levelling कार्यमा staff राख्दा ठिक vertical भएन भने त्यस्तो error लाई कुन error भनिन्छ ?", o:["Instrumental", "Personnel", "Natural", "कुनै पनि होइन"], a:1, e:"स्टाफ ठीक vertical (साहुल) नराखिनु मानवीय लापरवाही हो, त्यसैले यो Personal (personnel) error हो। स्टाफ ढल्किए reading सधैं बढी आउँछ, त्यसैले precise कामका लागि staff bubble वा plumb line प्रयोग गरिन्छ। Instrumental error (যেমন line of collimation को त्रुटि, staff graduation को त्रुटि) उपकरणबाट आउँछ, र Natural error (वायुमण्डलीय अपवर्तन, तापक्रम, वायुको झोंका, वर्षा) प्रकृतिबाट आउँछ।"},
      {q:"Levelling गर्दा सबै भन्दा पहिले reading लिने बिन्दु कुन हो ?", o:["Bench Mark", "Reference surface", "Unknown point", "जहाँ गरेपनि हुन्छ।"], a:0, e:"Levelling आरम्भ गर्नु अघि RL थाहा भएको बिन्दु (Bench Mark वा कुनै TBM/Change Point) मा पहिलो reading (back sight) लिनुपर्छ; त्यसैबाट Height of Instrument निकालिन्छ र त्यसपछि मात्र अन्य बिन्दुको RL निकाल्न सकिन्छ। RL अज्ञात बिन्दुबाट सुरु गरे त्यस आरम्भमा कुनै निरपेक्ष अर्थ रहँदैन।"},
      {q:"Levelling कार्यमा height of instrument को नाप ……………बाट लिईन्छ ?", o:["Ground", "Bench Mark", "Datum", "All of above"], a:2, e:"Height of instrument (HI) भन्नाले datum (सामान्यतया mean sea level) बाट line of sight (collimation को क्षितिज रेखा) सम्मको उचाई हो: HI = RL + back sight। यो जमिनबाट वा उपकरणको tripod को उचाई होइन - त्यसैले Ground विकल्प गलत हो।"},
      {q:"Staff को Graduation को कारणले गर्दा हुन आउने Error लाई के भनिन्छ ?", o:["Natural", "Instrumental", "Personal", "Compensating"], a:1, e:"स्टाफको graduation मा त्रुटि (तल्लो भाग घस्रिनु, चिन्ह बिग्रिनु, स्टाफको मापदण्ड नमिल्नु), level को समायोजनको त्रुटि जस्ता त्रुटि उपकरणबाटै आउने हुनाले यी Instrumental error हुन्। तिनको उपचार: स्टाफलाई standard tape वा invar staff सँग तुलना गर्ने, BS र FS को दूरी बराबर राख्ने।"},
      {q:"Plus sight भन्नाले", o:["Intermediate Reading", "Fore sight reading", "Back sight reading", "All of above"], a:2, e:"Back sight लाई Plus sight (वा positive sight) भनिन्छ, किनभने यो RL मा जोडेर Height of Instrument निकालिन्छ। Fore sight लाई Minus sight भनिन्छ, किनभने RL = HI - sight। Intermediate sight पनि घटाइन्छ, त्यसैले यो पनि minus-type sight हो, तर यसलाई सामान्यतया minus sight भन्ने चलन छैन।"},
      {q:"Levelling मा height of instrument भन्नाले के बुझिन्छ ?", o:["BM देखि line of sight सम्मको उचाई", "Datum देखि line of sight सम्मको उचाई", "जमिन देखि line of sight सम्मको उचाई", "Level instrument को उचाई"], a:1, e:"HI = datum देखि line of sight सम्मको उचाई = (RL of point) + back sight। पहिलो विकल्प तब मात्र मिल्छ जब instrument BM मै राखिएको छ (अन्यथा होइन), र जमिनबाटको उचाई वा उपकरणको भौतिक उचाईलाई HI भनिँदैन।"},
      {q:"Inclined staff मा लिइएको reading वास्तविक reading भन्दा", o:["घटि हुन्छ", "बढि हुन्छ", "दुबै हुनसक्छ", "फरक पर्दैन"], a:1, e:"स्टाफ ढल्किएमा cross-hair ले स्टाफको ठाडो उचाईभन्दा बढी (तिर्यक) दूरीमा काट्छ, त्यसैले reading सधैं बढी आउँछ र RL निकाल्दा त्रुटि पर्छ। उदाहरण: 2.895 m reading मा 8 cm ढल्किएको भए सही reading 2.8938 m हुन्छ (लगभग 1.1 mm को त्रुटि)।"},
      {q:"Positive sight भन्नाले कुन sight लाई जनाउँछ ?", o:["Back sight", "Fore sight", "Intermediate sight", "Turning sight"], a:0, e:"Back sight = positive/plus sight (RL मा जोडिन्छ)। Fore sight र Intermediate sight दुवै RL मा घटाइन्छन्, त्यसैले minus sight हुन्। Turning sight भन्ने अलग किसिमको sight हुँदैन - Change point मा लिइने reading FS र BS हुन्।"},
      {q:"Back sight and foresight distances are made equal for :", o:["speeding up the work", "balancing the line of sight", "minimizing the source of error", "none of these"], a:2, e:"बराबर BS र FS को दूरी राख्नुको उद्देश्य systematic errors - collimation (line of sight horizontal नहुनु), curvature र refraction - लाई कम गर्नु हो, किनभने यी त्रुटि दृष्टि दूरीसँग समानुपातिक हुन्छन् र बराबर दूरीमा क्रमशः खारेज हुन्छन्। यसले काम छिटो गर्दैन, बरु प्रत्येक setup मा distance नाप्नुपर्ने हुनाले केही ढिलो बनाउँछ; 'balancing the line of sight' भन्ने त यसै नियमको अर्को नाम मात्र हो।"},
      {q:"Cross section र longitudinal sectioning दुइबै के मा हुन्छ ?", o:["simple leveling", "profile leveling", "differential leveling", "check leveling"], a:1, e:"Profile levelling (longitudinal sectioning) मा centre line को प्रोफाइल र त्यसका साथै right angle दिशामा cross sections लिने काम दुवै समावेश हुन्छन्; cut र fill निकाल्न यी दुवै चाहिन्छन्। Simple levelling एउटै setup बाट दुई बिन्दुको उचाई फरक निकाल्ने विधि हो, differential levelling लामो distance मा धेरै setup बाट RL निकाल्ने सामान्य विधि, र check levelling (fly levelling) काम जाँच्न गरिने छिटो run हो।"},
      {q:"If the R.L. of B.M. is 100.00 m, the backsight is 1.215 m and foresight is 1.870 m, the R.L. of the forward station is:", o:["99.345 m", "100.345 m", "100.655 m", "101.870 m"], a:0, e:"R.L. = R.L. of B.M. + BS - FS = 100.000 + 1.215 - 1.870 = 99.345 m। FS ले BS भन्दा ठूलो भएकाले यो fall हो, त्यसैले forward station B.M. भन्दा तल पर्छ। यदि भूलवश जोड्दा 100.655 m आउँछ - त्यो सबैभन्दा सामान्य भूल हो।"},
      {q:"If the staff is not held vertical at a levelling station, the reduced level calculated from the observation would be", o:["true R.L.", "more than true R.L.", "less than true R.L.", "none"], a:2, e:"FS का रूपमा लिइएको reading स्टाफ ढल्किएमा बढी आउँछ, त्यसैले RL = HI - FS ले साँचोभन्दा घटी मान दिन्छ (यहाँ प्रश्न foresight पढाइको आधारमा गणना गरिएको RL को कुरा गरेको हो)। यदि बढी आउने reading BS हो भने HI बढी आउँछ र त्यसपछिका RL पनि बढी आउँछन् - त्यसैले स्टाफ ठाडो राख्नु अनिवार्य छ; सटीक काममा staff bubble वा plumb line प्रयोग गरिन्छ।"},
      {q:"With the rise of temperature, the sensitivity of a bubble tube", o:["decreases", "increases", "remains unaffected", "none of the above"], a:0, e:"तापक्रम बढ्दा tube भित्रको liquid फैलन्छ (expand हुन्छ) र vapour bubble छोटो हुन्छ; छोटो bubble को edge अस्पष्ट हुने र एक division ले ठूलो कोण बनाउने हुनाले tube को sensitivity घट्छ। यसै कारण गर्मीमा level लाई घाममा राख्नु हुँदैन; precise levelling मा तापक्रम बदलिँदा bubble को स्थिति फेरि जाँचिन्छ।"},
      {q:"Benchmark is established by", o:["hypsometry", "barometric leveling", "trigonometric leveling", "spirit leveling"], a:3, e:"Bench mark को स्थापना उच्च परिशुद्धताको spirit (precise) levelling बाट गरिन्छ; national network का GTS BM हरू यही विधिबाट datum सँग जोडिन्छन्। Barometric र hypsometric levelling ले लगभग 1 m को त्रुटि दिन्छन् (केवल reconnaissance का लागि), र trigonometric levelling पनि BM स्थापनाको लागि पर्याप्त शुद्ध हुँदैन।"},
      {q:"Level line कस्तो हुन्छ ?", o:["Horizontal", "Curve", "दुबै खालको", "ziczack"], a:1, e:"Level line भन्नाले स्थिर पानीको सतह जस्तै पृथ्वीको गोलापन अनुसरण गर्ने, सबै बिन्दुमा gravity प्रति लम्ब (perpendicular) रेखा हो - त्यसैले यो वक्र (curve) हुन्छ। Horizontal line भने एक बिन्दुमा level line प्रति tangent खिचिएको सीधा रेखा हो। लामो दृष्टि दूरीमा यी दुई फरक हुन्छन् (1 km मा लगभग 0.0785 m), त्यसैले curvature correction दिनुपर्छ।"},
      {q:"Inverted staff लाई कस्तो अवस्थामा प्रयोग गरिन्छ ?", o:["Reciprocal leveling", "ताल वा नदिमा leveling गर्दा", "Building को ceiling मा leveling गर्दा", "summit मा leveling गर्दा"], a:2, e:"Building को ceiling, beam/girder को soffit, पुलको underside जस्ता line of sight भन्दा माथि पर्ने बिन्दुको RL निकाल्न स्टाफ उल्टो (graduation zero माथि) राखिन्छ; reading level book मा minus sign सहित लेखिन्छ र RL = HI + reading हुन्छ। ताल/नदिमा भने reciprocal levelling गरिन्छ (स्टाफ सामान्य अवस्थामै राखिन्छ), र summit मा trigonometric/GNSS विधि प्रयोग गरिन्छ।"},
      {q:"Refraction correction equals to:", o:["0.0785 D squared m", "0.0112 D squared m", "0.0773 D squared m", "None"], a:1, e:"Refraction correction Cr = 0.0112 D squared m, जहाँ D किलोमिटरमा दृष्टि दूरी हो; वायुमण्डलले दृष्टि रेखालाई तलतिर बङ्ग्याउने हुनाले यो correction additive (जोडिने) हुन्छ। 0.0785 D squared curvature correction हो (subtractive), र 0.0673 D squared दुवैको combined correction (0.0785 - 0.0112) हो।"},
      {q:"Turning points means-", o:["Bench mark", "datum", "Station", "change point."], a:3, e:"Turning point र change point एकै हो - त्यो बिन्दु जहाँ instrument सार्नु अघि fore sight र सारेपछि back sight लिइन्छ। BM भनेको RL थाहा भएको स्थायी बिन्दु हो, datum भनेको उचाई नापिने आधार सतह (MSL) हो, र station भनेको instrument राखिएको वा स्टाफ राखिएको बिन्दु हो।"},
      {q:"Staff reading over a station, whose elevation is not known is called..", o:["Back sight", "Fore Sight", "Intermediate Sight", "Fore sight र Intermediate sight दुबै"], a:3, e:"RL अज्ञात बिन्दुमा लिइने reading दुई प्रकारको हुन्छ: Fore sight (change point मा, instrument सार्नु अघि लिइने अन्तिम reading) र Intermediate sight (दुई change point बीच अन्य बिन्दुमा लिइने reading)। दुवैलाई height of instrument बाट घटाइन्छ। Back sight भनेको RL थाहा भएको बिन्दुमा लिइन्छ, त्यसैले यहाँ लागू हुँदैन।"},
      {q:"Levelling कार्यमा कस्तो अवस्थामा Fore staff Inverted राखिन्छ ?", o:["station horizontal line भन्दा तल भएमा ।", "station horizontal line भन्दा माथि भएमा", "station horizontal line मा भएमा ।", "Staff inverted राखिदैन ।"], a:1, e:"जुन बिन्दुको RL निकाल्नु छ त्यो line of sight (horizontal line) भन्दा माथि छ भने - जस्तै ceiling, beam को soffit, over-bridge - स्टाफ उल्टो राखिन्छ। तब reading लाई minus sight भनी book गरिन्छ र बिन्दुको RL = HI + reading हुन्छ। बिन्दु horizontal line भन्दा तल भएमा स्टाफ सामान्य (ठाडो) राखिन्छ।"},
      {q:"Combined correction for curvature and refraction is given by", o:["0.0785 D squared", "0.06735 D squared", "0.0112 D squared", "All of above"], a:1, e:"Curvature correction subtractive = 0.0785 D squared र refraction correction additive = 0.0112 D squared हुनाले combined correction = (0.0785 - 0.0112) D squared = 0.0673 D squared m (D किलोमिटरमा)। यो correction सधैं subtractive हुन्छ, अर्थात् reading बाट घटाइन्छ, किनभने curvature को प्रभाव (reading बढी आउनु) refraction को प्रभावभन्दा ठूलो हुन्छ।"},
      {q:"लेभल लाईन र प्लम्ब लाईन बीच कस्तो सम्बन्ध हुन्छ ?", o:["Parallel", "coincide", "perpendicular", "No relation between them"], a:2, e:"Plumb line (साहुल रेखा) गुरुत्वको दिशा जनाउने रेखा हो र level line (वा horizontal line कुनै एक बिन्दुमा) त्यसै बिन्दुमा plumb line प्रति लम्ब हुन्छ। यही सम्बन्धका कारण level को vertical axis लाई bubble tube को axis प्रति perpendicular बनाइन्छ - जसले bubble centre मा हुँदा line of sight horizontal हुन्छ।"},
      {q:"Levelling कार्यमा station भन्नाले के लाई बुझाउँछ ?", o:["Staff position", "Instrument Position", "Bench Mark", "Both (a) and (c)"], a:1, e:"Levelling मा 'station' भन्नाले सामान्यतया level (instrument) राखिएको बिन्दुलाई बुझाउँछ; यही अर्थ यही फाइलका अन्य प्रश्नहरू (station = level set गरेको ठाउँ) मा पनि प्रयोग भएको छ। Staff राखिएको बिन्दुलाई staff station भनिन्छ, र प्रश्नले Bench Mark लाई station भन्दैन। ध्यान दिनुहोस्: केही पाठ्यपुस्तकमा 'levelling station' भन्दा स्टाफ राखिएको बिन्दुलाई जनाउने चलन पनि छ - परीक्षामा यही फाइलको प्रयोग अनुसार instrument position लाई उत्तर मान्नुहोस्।"},
      {q:"Which one of following is indirect method of leveling ?", o:["Trigonometric levelling", "Barometric levelling", "Hypsometric leveling", "All of above"], a:3, e:"Trigonometric levelling (उचाई फरक vertical angle र horizontal distance बाट निकाल्ने), barometric levelling (वायुमण्डलीय चापबाट) र hypsometric levelling (पानी उम्लने तापक्रम/उचाई-सम्बन्धबाट) - तीनवटै indirect (अप्रत्यक्ष) विधि हुन्। Spirit levelling मात्र direct विधि हो, जहाँ line of sight horizontal राखी स्टाफको सिधा reading लिइन्छ।"},
      {q:"Levelling अन्तर्गत तलका कुन प्रक्रिया गरिदैन ?", o:["Centering", "Levelling", "Orientation", "A र C दुबै"], a:3, e:"Levelling मा उपकरणलाई station को ठीक माथि राख्ने centring गर्नु पर्दैन (theodolite/ total station मा जस्तो) र कुनै ज्ञात रेखासँग मिलाउने orientation पनि गर्नु पर्दैन; गर्नुपर्ने भनेको उपकरणलाई ठीक तहमा राख्नु (levelling) र focusing गर्नु मात्र हो। त्यसैले A र C दुवै levelling अन्तर्गत पर्दैनन्।"},
      {q:"कुन RL बढी शुद्ध मानिन्छ ?", o:["B.M", "Trig-Point", "दुवै बराबर", "कुनै पनि होइन"], a:0, e:"Bench Mark को RL precise spirit levelling बाट स्थापित हुन्छ र त्यसको closing error कडा सीमाभित्र राखिन्छ, त्यसैले यो trig-point (trigonometrical levelling/नेटवर्कबाट निकालिएको) भन्दा बढी शुद्ध मानिन्छ। त्रुटिको तुलना: precise levelling लगभग 1.1 वर्गमूल K mm, trigonometrical levelling horizontal दूरीको लगभग 1/5,000 - 1/10,000।"},
      {q:"Which of the following error is eliminated in reciprocal leveling?", o:["Zero Error", "Graduation Error", "Collimation Error", "Curvature and Refraction Error"], a:3, e:"Reciprocal levelling ले curvature र refraction को त्रुटि (साथै line of collimation को त्रुटि) लाई दुईतिरबाट लिइएको अवलोकनको औसत लिएर हटाउँछ। Zero error (स्टाफको तल्लो भाग घस्रिने) र graduation error (स्टाफको मापदण्ड बिग्रिने) स्टाफसँग सम्बन्धित भएकाले reciprocal विधिले हटाउँदैन - ती स्टाफ जाँचेर (standard tape सँग तुलना गरी) मात्र कम गर्न सकिन्छ।"},
      {q:"Levelling मा Change Point (turning point) छनोट गर्दा कस्तो बिन्दु रोज्नुपर्छ ?", o:["भर्खरै खनेको नरम माटो भएको ठाउँ", "स्थिर, कडा र उपकरण सार्दा नसर्ने बिन्दु (ढुङ्गा, peg, staff plate)", "जहाँ पनि हुन्छ, फरक पर्दैन", "पानी जमेको वा दलदल ठाउँ"], a:1, e:"Change point मा instrument सार्नु अघि fore sight र सारेपछि back sight लिइन्छ; यी दुई reading बीच बिन्दु होचो वा सर्ने भयो भने पूरै levelling line मा systematic error पस्छ र closing error बढ्छ। त्यसैले ढुङ्गा, गाडिएको peg वा staff plate जस्तो स्थिर र कडा बिन्दु रोजिन्छ। (यही फाइलमा 'Positive sight = back sight' सोध्ने दुई प्रश्न दोहोरो भएकाले यो प्रश्न अलग महत्त्वपूर्ण तथ्यमा परिवर्तन गरिएको हो।)"},
      {q:"लेभलिङ सर्मैमा कुनै known RL भएको बिन्दुमा लिइएको staff reading लाई के भनिन्छ ?", o:["Fore sight reading", "Back sight reading", "Change point reading", "All"], a:1, e:"RL थाहा भएको बिन्दु (BM वा change point) मा लिइने reading back sight हो र यो RL मा जोडिन्छ। Change point reading भन्ने अलग reading हुँदैन - change point मा FS र BS गरी दुई reading लिइन्छन्।"},
      {q:"नापी विभाग खगोल तथा भू-मापन महाशाखाले प्रकाशन गरेको leveling instruction book लाई के भनिन्छ ?", o:["Blue book", "Black book", "Yellow book", "Red book"], a:0, e:"नेपालको नापी विभागले levelling सम्बन्धी मापदण्ड, त्रुटिको सीमा (permissible error), फिल्ड विधि र प्रतिवेदनको ढाँचा समेटेको जुन instruction book प्रकाशित गरेको छ, त्यसलाई व्यवहारमा 'Blue Book' भनिन्छ। यसैमा उल्लेख भएको अनुसार उच्च परिशुद्धताको levelling मा permissible closing error 1.1 वर्गमूल K mm (K किलोमिटरमा) तोकिएको छ।"},
      {q:"Mean sea level को उचाई कति कायम गरिएको छ ?", o:["0 m", "100 m", "1000 m", "10000 m"], a:0, e:"Datum का रूपमा मानिएको mean sea level को उचाई 0 m कायम गरिन्छ, र त्यसैका आधारमा सबै बिन्दुको RL धनात्मक (वा समुद्र सतहभन्दा तल भए ऋणात्मक) हुन्छ। नापीमा प्रायः दीर्घकालीन (19 वर्षे) ज्वारभाटाको औसत सतहलाई MSL मानिन्छ - भारतमा मुम्बईको MSL मानिएको छ।"},
      {q:"Datum बाट line of sight सम्मको दुरीलाई के भनिन्छ ?", o:["Reduced level", "Height of instrument", "Height of target", "Instrument of height"], a:1, e:"Datum बाट line of sight सम्मको ठाडो दूरी height of instrument (HI) हो: HI = (RL of point) + BS। Reduced level कुनै बिन्दुको उचाई हो (datum बाट त्यस बिन्दुसम्म), र height of target (target staff मा) स्टाफको target सम्मको उचाई जनाउँछ - प्रश्नसँग मेल खाँदैन।"},
      {q:"लेभल यन्त्रमा axis of bubble tube र vertical axis को सम्बन्ध कस्तो हुन्छ ?", o:["Concide", "Parallel", "Perpendicular", "जुनसुकै हुन सक्छ"], a:2, e:"Permanent adjustment को आधारभूत शर्त: bubble tube को axis vertical axis (plumb line) प्रति लम्ब हुनुपर्छ। तब bubble centre मा आउँदा bubble tube को axis horizontal हुन्छ र line of collimation पनि horizontal हुन्छ। यदि यी अक्षहरू लम्ब छैनन् भने bubble centre हुँदा पनि line of sight तिर्यक हुन्छ - यही collimation error हो, जुन two-peg test ले जाँचिन्छ।"},
      {q:"Leveling मा दुईय staff को विचमा Instrument किन राखिन्छ ?", o:["collimation error हटाउन", "collimation error घटाउन", "collimation error बढाउन", "collimation error नै हुँदैन"], a:0, e:"उपकरण दुई स्टाफको ठीक बीचमा (BS = FS दूरी) राख्दा line of collimation को त्रुटि, curvature र refraction को प्रभाव दुवै तिर बराबर हुन्छन् र reading को फरक (RL फरक) निकाल्दा पूर्ण रूपमा खारेज हुन्छन् - त्यसैले यो त्रुटि 'घट्ने' मात्र नभई हट्छ। collimation error कहिल्यै हुँदैन भन्ने कुरा गलत हो; उपकरणको समायोजन त्रुटि सधैं हुनसक्छ, बराबर दूरीले त्यसलाई असरहीन बनाउँछ।"},
      {q:"During levelling if back sight is more than foresight", o:["The forward staff is at lower point", "The back staff is at lower point", "The difference in level, cannot be ascertained", "None of these"], a:1, e:"BS > FS भए fall (घटी) पर्छ, अर्थात् पछाडिको (back staff) बिन्दु अगाडिको भन्दा तल छ: RL अगाडिको = RL पछाडिको + BS - FS, र BS > FS हुँदा RL बढ्छ। यसैले BS < FS भए back station माथि हुन्छ। यो तर्क arithmetic check (योग BS - योग FS = अन्तिम RL - पहिलो RL) सँग पनि मिल्छ।"},
      {q:"Determining the difference in elevation between two points on the surface of the earth, is known as", o:["Levelling", "Simple leveling", "Differential leveling", "Longitudinal levelling"], a:2, e:"दुई बिन्दुबीचको उचाई फरक निकाल्नु सामान्य अर्थमा levelling हो, तर परीक्षाको अपेक्षित उत्तर differential levelling हो: जब बिन्दुहरू टाढा छन् वा बीचमा अवरोध छ र एउटै setup बाट काम हुँदैन, धेरै setup का change point हुँदै जोडिने विधिलाई differential levelling भनिन्छ। Simple levelling एउटै setup बाट हुने सामान्य अवस्था हो, र longitudinal levelling (profile levelling) line का साथ प्रोफाइल निकाल्ने काम हो।"},
      {q:"तलका मध्ये शुद्ध leveling कुन हो ?", o:["Trigonometric leveling", "Barometric leveling", "Spirit leveling", "Hypsometric leveling"], a:2, e:"Spirit (sprit) leveling सबैभन्दा शुद्ध (accurate) विधि हो - यसमा line of sight horizontal राखी स्टाफको सिधा reading लिइन्छ र closing error 1.1 वर्गमूल K mm (उच्च परिशुद्धता) जत्तिकै कम राख्न सकिन्छ। Trigonometric levelling (vertical angle बाट) को शुद्धता लगभग 1/5,000 - 1/10,000, र barometric/hypsometric levelling को लगभग 1 m मात्र हुन्छ।"},
      {q:"Level instrument मा telescope किन राखिन्छ ?", o:["Line of sight horizontal बनाउन", "line of sight provide गर्न", "bubble लाई centre मा ल्याउन", "माथिका सबै कार्य गर्न"], a:1, e:"Telescope को मुख्य काम distant स्टाफको reading स्पष्ट देखिने (magnified) image बनाई line of sight उपलब्ध गराउनु हो; cross-hair र focusing ले त्यही दृष्टि रेखामा reading लिन मद्दत गर्छ। Line of sight horizontal बनाउने काम foot screws/tilting screw र bubble को हो, र bubble लाई centre मा ल्याउने काम level को levelling head (foot screws) को - त्यसैले 'माथिका सबै' उत्तर होइन।"},
      {q:"A relatively fixed point of known elevation above datum, is called", o:["Bench mark", "Datum point", "Reduced level", "Reference point"], a:0, e:"Bench mark स्थायी रूपमा स्थापित, RL थाहा भएको बिन्दु हो - यो 'relatively fixed' (स्थिर रहने) हुनुपर्छ, त्यसैले यसलाई प्रायः भवन, पुल, ठूला ढुङ्गा वा विशेष रूपमा गाडिएको चिन्हमा राखिन्छ। Datum point वा reference point भन्ने शब्दले सामान्य आधार बिन्दुलाई जनाउँछ तर नापीको परिभाषा bench mark नै हो; RL भनेको उचाईको मान हो, बिन्दु होइन।"},
      {q:"The surface of zero elevation around the earth, which is slightly irregular and curved, is known as", o:["Mean sea level", "Geoid surface", "Level surface", "Horizontal surface"], a:1, e:"Geoid सतह भन्नाले mean sea level सँग नजिक मिल्ने, तर पृथ्वीभित्रको द्रव्यमान वितरणको भिन्नताले गर्दा हल्का अनियमित (lumpy) र वक्र हुने, शून्य उचाईको समसामर्थ (equipotential) सतह हो। प्रश्नमा 'slightly irregular and curved' भनिएकाले geoid surface अपेक्षित उत्तर हो। MSL भनेको स्थानीय समुद्रको औसत सतह (लगभग 19 वर्षको ज्वारभाटाको औसत) हो, level surface गुरुत्व प्रति सबैतिर लम्ब हुने सतह हो, र horizontal surface एक बिन्दुमा खिचिएको सीधा समतल हो।"},
      {q:"बक्रता र आवर्तनको संसोधनको शुत्र के हो ?", o:["0.67 D squared", "0.067 D squared", "0.0673 D squared", "0.007 D squared"], a:2, e:"Curvature र refraction को combined correction = (0.0785 - 0.0112) D squared = 0.0673 D squared m, जहाँ D किलोमिटरमा दृष्टि दूरी हो; यो correction subtractive हो, अर्थात् reading बाट घटाइन्छ। छुट्टाछुट्टै: curvature 0.0785 D squared (subtractive) र refraction 0.0112 D squared (additive)।"},
      {q:"Vertical axis सँग Bubble tube को Axis के हुनु पर्दछ ?", o:["समकोण", "समानान्तर", "सिधा", "माथिको सबै हुनुपर्छ"], a:0, e:"Bubble tube को axis vertical axis (plumb line) सँग समकोण (90 डिग्री) हुनुपर्छ - यो level को दोस्रो permanent adjustment हो। यसो भएमा bubble centre मा आउँदा line of collimation पनि horizontal हुन्छ र सही RL निकाल्न सकिन्छ; यदि समानान्तर वा तिर्यक भयो भने bubble centre हुँदा पनि दृष्टि रेखा ढल्किन्छ (collimation error)।"},
      {q:"Levelling मा zero error कम्मो error हो ?", o:["Instrumental", "Personal", "Natural", "All of the above"], a:0, e:"Zero error भन्नाले स्टाफको तल्लो भाग घस्रिनु वा स्टाफको zero चिन्ह बिग्रिनु हो - यो उपकरणसँग सम्बन्धित भएकाले Instrumental error हो। यसको उपचार: स्टाफको तल्लो भागमा धातुको shoe हुनु, स्टाफलाई निरन्तर जाँच्नु (standard tape सँग तुलना), र BS र FS को दूरी बराबर राख्नु।"},
      {q:"कुनको RL बढी शुद्ध मानिन्छ ?", o:["B.M.", "Trig-Point", "Clinometer बाट आएको R.L.", "Spot hight को R.L."], a:0, e:"B.M. को RL precise spirit levelling बाट स्थापित हुन्छ र यसको closing error कडा सीमाभित्र राखिन्छ (Blue Book अनुसार उच्च परिशुद्धतामा 1.1 वर्गमूल K mm), त्यसैले यो trig-point, clinometer (barometric/कोणमापक) वा spot height भन्दा बढी शुद्ध हुन्छ। Trig-point trigonometric levelling बाट, spot height प्रायः map/photo बाट आउँछ - ती दुवैको शुद्धता न्यून हुन्छ।"},
      {q:"लेभलिङ्ग गर्दा सबभन्दा पहिले लिइने reading कुन हो ?", o:["Back sight reading", "Fore sight reading", "B.M. reading", "माथिको कुनै पनि होइन"], a:0, e:"उपकरण setup गरेपछि सबैभन्दा पहिले RL ज्ञात बिन्दु (BM वा change point) मा लिइने reading लाई back sight भनिन्छ; त्यसैबाट HI = RL + BS निकालिन्छ। BM reading पनि back sight नै हुन्छ, तर प्रश्नले पहिलो reading को प्रकार सोधेकाले सही उत्तर Back sight reading हो।"},
      {q:"When the bubble of the level tube of a level, remains central", o:["Line of sight is horizontal", "Axis of the telescope is horizontal", "Line of collimation is horizontal", "Geometrical axis of the telescope is horizontal"], a:2, e:"Bubble centre मा हुँदा bubble tube को axis र त्यसैले line of collimation (cross-hair र objective को optical centre जोड्ने रेखा) horizontal हुन्छ। Telescope को geometrical axis र line of sight (line of collimation) फरक कुरा हुन् - objective र eyepiece को केन्द्र जोड्ने axial line horizontal हुनु आवश्यक छैन।"},
      {q:"The line normal to the plumb line is known as", o:["Horizontal line", "Level line", "Datum line", "Vertical line"], a:0, e:"Plumb line प्रति लम्ब (normal) रेखा horizontal line हो - यो सीधा र एक बिन्दुमा मात्र लागू हुन्छ। Level line गुरुत्व प्रति लम्ब हुने (पानीको सतह जस्तै) वक्र रेखा हो; यो पनि plumb line प्रति लम्ब हुन्छ तर एकै बिन्दुमा level line र horizontal line tangent हुन्छन्। Datum line कुनै तोकिएको आधार रेखा हो।"},
      {q:"Levelling गर्दा Level Instrument लाई दुई स्टाफको बीचमा राखेर reading गर्दा कुन error हट्छ ?", o:["Graduation", "Collimation", "refraction", "Natural"], a:1, e:"उपकरण दुई स्टाफको बीचमा (बराबर BS र FS दूरीमा) राख्दा line of collimation को त्रुटि हट्छ - किनभने त्रुटि दृष्टि दूरीसँग समानुपातिक हुन्छ र बराबर दूरीमा दुवै reading मा बराबर परेर फरक (RL फरक) निकाल्दा खारेज हुन्छ। Curvature र refraction पनि यही कारण हट्छन्; graduation error भने स्टाफकै त्रुटि भएकाले हट्दैन।"},
      {q:"Levelling कार्यमा staff राख्दा observer तिर ढल्किएमा आउने error लाई कुन error भनिन्छ ?", o:["Instrumental", "Personel", "Natural", "कुनैपनि होईन"], a:1, e:"स्टाफ observer तिर वा कुनै पनि दिशामा ढल्काउनु व्यक्तिको लापरवाही हो, त्यसैले यो Personal error हो; यसले reading बढी आउने त्रुटि गराउँछ। Instrumental error उपकरणको समायोजन/graduation बाट, र Natural error वायुमण्डलीय तथा प्राकृतिक कारण (refraction, तापक्रम, वायु, वर्षा, स्टाफको परछाई) बाट आउँछ।"},
      {q:"पृथ्वीको spherical surface (MSL) सँग Parallel रहेको सतहलाई के भनिन्छ ?", o:["Horizontal surface", "Vertical surface", "Level surface", "Geoid surface"], a:2, e:"Mean sea level सँग समानान्तर, गुरुत्व प्रति सबैतिर लम्ब हुने र पृथ्वीको गोलापन अनुसरण गर्ने सतह level surface हो; स्थिर पानीको सतह यसको सबैभन्दा नजिकको उदाहरण हो। Horizontal surface कुनै एक बिन्दुमा खिचिएको सीधा समतल हो (level surface प्रति tangent), vertical surface ठाडो समतल, र geoid शून्य उचाईको सैद्धान्तिक equipotential सतह हो।"},
      {q:"Levelling मा Back र fore staff reading दुबै reading लिने बिन्दुलाई के भनिन्छ ?", o:["Change point", "Turning point", "माथिका दुबै", "Known point"], a:2, e:"Change point र turning point एउटै बिन्दुका दुई नाम हुन् - जहाँ instrument सार्नु अघि fore sight र सारेपछि back sight लिइन्छ। यो बिन्दु स्थिर, कडा (ढुङ्गा, peg, स्टाफ plate) हुनुपर्छ; होइन भने बीचमा धसिँदा पूरै line मा systematic error पस्छ। त्यसैले सही उत्तर 'माथिका दुबै' हो।"},
      {q:"Levelling कार्यमा instrument राखिएको ठाउँलाई के भनिन्छ ?", o:["station", "change point", "observation station", "माथिका कुनै पनि होइन"], a:0, e:"उपकरण राखिएको ठाउँलाई station (instrument station) भनिन्छ; यही अर्थ यही फाइलको अर्को प्रश्नले पनि जनाएको छ। Change point भनेको स्टाफ राखिने र जहाँबाट levelling अगाडि बढाइन्छ त्यो बिन्दु हो - उपकरण राखिने ठाउँ होइन।"},
      {q:"कुनै पनि ताल (पोखरी) मा रहेको स्थिर पानीको सतहले के लाई जनाउँछ ?", o:["Vertical Surface", "Horizontal surface", "level surface", "Oblique surface"], a:2, e:"स्थिर पानीको सतह सधैं level surface हुन्छ - यो गुरुत्वको दिशा प्रति सबैतिर लम्ब र पृथ्वीको गोलापन अनुसरण गर्ने वक्र सतह। यसैले लामो दूरीमा दृष्टि रेखा पानीको सतहभन्दा माथि जान्छ (1 km मा लगभग 0.0785 m) र curvature correction दिनुपर्छ। Horizontal surface भने एक बिन्दुमा मात्र पानीको सतहसँग मिल्छ।"},
      {q:"Indirect method या levelling भन्नाले कुन levelling लाई बुझाउँछ ?", o:["triciac levelling", "Trigonometric levelling", "spirit levelling", "All of above"], a:1, e:"Indirect levelling का मुख्य विधिहरू trigonometric levelling, barometric levelling र hypsometric levelling हुन्; यसमध्ये सबैभन्दा बढी प्रयोग हुने र शुद्ध मानिने trigonometric levelling हो। Spirit levelling direct विधि हो, त्यसैले यो विकल्प गलत हो। (triciac भन्ने शब्द नै मान्य छैन; सम्भवतः trigonometrical को अपभ्रंश हो।)"},
      {q:"कुनै एउटा leveling कार्यमा बिन्दु A को staff Reading 1.432 m र बिन्दु B को staff reading 0.541 m रहेछ । यदि बिन्दु B को उचाई 1550 m भए A को उचाई कति होला ?", o:["1549.109 m", "1550.541 m", "1550.891 m", "1551.432 m"], a:0, e:"A मा 1.432 m र B मा 0.541 m reading हुँदा B को reading सानो भएकाले B माथि छ (B बाट A तिर fall हो): RL(A) = RL(B) + reading at B - reading at A = 1550.000 + 0.541 - 1.432 = 1549.109 m। अर्थात् A, B भन्दा 0.891 m तल पर्छ। 1550.891 m विकल्प उल्टो चिन्ह लगाउँदा आउने सामान्य भूल हो।"},
      {q:"Levelling मा नाप लिने कार्य कुन सतहमा गरिन्छ ?", o:["Horizontal plane", "Vertical Plane", "Both of above", "Slope Plane"], a:0, e:"Spirit levelling मा दृष्टि रेखा (line of sight) horizontal हुन्छ र स्टाफको reading त्यही horizontal plane मा लिइन्छ; नापिने राशि भने vertical दूरी (उचाई) हो। यसैले 'नाप लिने' कार्य horizontal plane मा हुन्छ तर नापको परिणाम vertical plane मा आउँछ - यही भिन्नता बुझ्नु महत्त्वपूर्ण छ।"},
      {q:"Leveling को सन्दर्भमा कुन कथन सही हो ?", o:["Station भन्नाले Level set गरेको ठाउँ हो ।", "Station भन्नाले Stadia rod राखेको ठाउँ हो ।", "Station भन्नाले computer बसेको ठाउँ हो ।", "माथिका कुनै पनि होइन ।"], a:0, e:"Levelling मा station भन्नाले उपकरण (level) set गरेको ठाउँलाई जनाउँछ; स्टाफ राखिएको बिन्दुलाई staff station भनिन्छ। (कतिपय पुस्तकमा 'levelling station' ले स्टाफ राखिएको बिन्दुलाई जनाउने चलन पनि छ, तर यही फाइलका अन्य प्रश्नसँग मेल खाने उत्तर instrument station नै हो।)"},
      {q:"खगोल तथा भूमापन महाशाखाले leveling instruction book मा दिए अनुसार उच्च परिशुद्धताको लेभलिङ्ग मा permissible error कति छ ?", o:["1.1 वर्गमूल K mm", "2.0 वर्गमूल K mm", "5.0 वर्गमूल K mm", "All"], a:0, e:"नापी विभागको leveling instruction (Blue Book) अनुसार उच्च परिशुद्धता (first order) levelling मा permissible closing error = 1.1 वर्गमूल K mm, जहाँ K किलोमिटरमा लेभलिङ लाइनको लम्बाई हो। दोस्रो श्रेणी/सामान्य (ordinary) levelling का लागि यो भन्दा ठूलो मान (लगभग 12 वर्गमूल K वा 25 वर्गमूल K mm) दिइन्छ - त्यसैले यहाँ 1.1 वर्गमूल K mm सबैभन्दा कडा र सही विकल्प हो।"},
      {q:"Levelling मा कुन error हुँदैन ?", o:["Natural", "Personal", "Instrumental", "Centering"], a:3, e:"Levelling मा त्रुटिका तीन मुख्य समूह हुन्छन् - Instrumental (उपकरणको समायोजन, स्टाफको graduation, zero error), Personal (स्टाफ ठाडो नराख्नु, भूल reading/booking) र Natural (curvature, refraction, तापक्रम, वायु, वर्षा)। Centering error भने theodolite/total station मा हुन्छ (केन्द्रबाट उपकरण सर्नु); levelling मा उपकरणलाई केन्द्रित गर्नु पर्दैन, त्यसैले यो त्रुटि levelling मा हुँदैन।"},
      {q:"नदिका दुई किनारामा पर्ने बिन्दुहरुको levelling कुन विधि उत्तम छ ?", o:["Differential levelling", "Fly levelling", "Check levelling", "Reciprocal levelling"], a:3, e:"नदीको दुई किनारामा उपकरण ठीक बीचमा राख्न सकिँदैन, त्यसैले दुवै किनारबाट (दुई setup) अवलोकन गरी औसत लिने reciprocal levelling नै उत्तम हो - यसले curvature, refraction र collimation error लाई हटाउँछ। Differential levelling ले धेरै setup हुँदै जोड्छ तर त्रुटि खारेज गर्दैन; fly levelling छिटो जाँच्ने र check levelling काम जाँच्ने विधि हो।"},
      {q:"Height of instrument method of levelling is", o:["more accurate than rise and fall method", "less accurate than rise and fall method", "quicker & less tedious for large number of I.S.", "none of the above"], a:2, e:"Height of instrument method मा प्रत्येक setup मा एउटै HI बाट धेरै intermediate sights घटाएर RL निकालिन्छ, त्यसैले धेरै IS भएको काममा यो छिटो र कम झन्झटिलो हुन्छ। दुवै विधि arithmetic रूपमा बराबर शुद्ध हुन्छन् (एउटै परिणाम दिन्छन्); फरक भनेको rise and fall विधिले प्रत्येक IS मा पनि check दिन्छ, त्यसैले मात्र यो बढी भरपर्दो मानिन्छ।"},
      {q:"In reciprocal levelling, the error which is not completely eliminated, is due to", o:["Earth's curvature", "Non-adjustment of line of collimation", "Refraction", "Non-adjustment of the bubble tube"], a:2, e:"दुई किनारबाट लिइएको अवलोकनको औसत लिँदा curvature र line of collimation सम्बन्धी त्रुटि खारेज हुन्छन्, तर refraction को त्रुटि पूर्ण रूपमा हट्दैन - किनभने वायुको तापक्रम, चाप र आर्द्रता समय-समयमा बदलिने हुनाले दुईतिरको दृष्टि रेखा बराबर बङ्गिन्न। यसैले लामो दूरीमा दृष्टि रेखालाई पानीको सतहबाट कम्तीमा 1 m माथि राख्ने, शान्त बिहान/साँझ वा रातमा अवलोकन गर्ने जस्ता उपाय अपनाइन्छ।"},
      {q:"The back staff reading on a B.M. of R.L. 500.000 m is 2.685 m. If foresight reading on a point is 1.345 m, the reduced level of the point, is", o:["502.685 m", "501.345 m", "501.340 m", "504.030 m"], a:2, e:"RL = 500.000 + 2.685 - 1.345 = 501.340 m। यहाँ FS (1.345) BS (2.685) भन्दा सानो भएकाले यो rise हो र बिन्दुको RL B.M. भन्दा 1.340 m माथि पर्छ। 501.345 m विकल्प तब आउँछ जब BS लाई गल्तीले बिर्सेर जोडिन्छ।"},
      {q:"In levelling operation", o:["When the instrument is being shifted, the staff must not be moved", "When the staff is being carried forward, the instrument must remain stationary", "Both A and B", "Neither A nor B"], a:2, e:"Levelling मा क्रम यही हुनुपर्छ: (i) instrument सार्दा स्टाफ बिल्कुल हल्लाउनु हुँदैन - नत्र change point मा लिइएको FS र BS बीच बिन्दु सर्छ र त्रुटि पस्छ; (ii) स्टाफ अगाडि बढाउँदा उपकरण आफ्नै ठाउँमा स्थिर राखिएको हुनुपर्छ। त्यसैले A र B दुवै सही हुन्। साथै instrument र staff को tripod/ठाउँ जोड्ने जमिन स्थिर हुनुपर्छ।"},
      {q:"Levelling मा station भनेको कुन बिन्दुलाई जनाउँदछ ?", o:["Instrument राखेको बिन्दुलाई", "Back sight मा स्टाफ राखेको बिन्दुलाई", "Fore sight मा स्टाफ राखेको बिन्दुलाई", "स्टाफहरु राखेको बिन्दुलाई"], a:0, e:"Levelling को सामान्य प्रयोगमा station भन्नाले instrument (level) राखिएको बिन्दु जनाउँछ; यही फाइलका अन्य प्रश्न (station = level set गरेको ठाउँ) सँग पनि यो अर्थ मिल्छ। स्टाफ राखिएको बिन्दुलाई भने staff station भनिन्छ, जसलाई BS स्टाफ बिन्दु, FS स्टाफ बिन्दु वा change point भनी छुट्याइन्छ।"},
      {q:"levelling कार्यमा", o:["दोश्रो reading पहिलो भन्दा वढि भएमा rise हुन्छ", "पहिलो reading दोश्रो भन्दा वढि भएमा rise हुन्छ", "पहिलो reading दोश्रो भन्दा कम भएमा fall हुन्छ", "विकल्प (ख) र (ग) दुबै सही छन्"], a:3, e:"Rise and fall को आधार: पहिलो reading - दोश्रो reading = धनात्मक भए rise, ऋणात्मक भए fall। विकल्प (ख): पहिलो reading दोश्रो भन्दा बढी ⇒ rise ✓; विकल्प (ग): पहिलो reading दोश्रो भन्दा कम ⇒ fall ✓। विकल्प (क) ठीक विपरीत भएकाले गलत हो। त्यसैले सही उत्तर (ख) र (ग) दुबै हो।"},
      {q:"सिधा स्टाफको रिडिंग ढल्केको स्टाफको रिडिंग भन्दा के हुन्छ ?", o:["बराबर", "कम", "बढि", "माथिको सबै"], a:1, e:"स्टाफ ठाडो हुँदा cross-hair ले स्टाफको लम्ब दिशामा काट्छ (सबैभन्दा छोटो मान), ढल्काउँदा त्यही horizontal line ले स्टाफमा अझ माथिल्लो (ठूलो) अंक काट्छ। त्यसैले ठाडो स्टाफको reading ढल्केको स्टाफको reading भन्दा सधैं कम हुन्छ, र ढल्किएको reading ले त्रुटि निम्त्याउँछ। सही reading = वर्गमूल (reading squared - ढल्किएको मात्रा squared)।"},
      {q:"वायु मण्डलिय चापलाई आधार मानेर उचाई निकाल्ने विधि कुन हो ?", o:["Barometric levelling", "Spirit levelling", "Trigonometric levelling", "Reciprocal leveling"], a:0, e:"Barometric levelling मा altimeter (परिष्कृत aneroid barometer) ले वायुमण्डलीय चाप नापी उचाई निकालिन्छ; चापसँगै उचाई अनुमान गर्ने सम्बन्ध प्रयोग गरिन्छ (लगभग 1 mm पाराको चाप ≈ 11 m उचाई)। शुद्धता जम्मा लगभग 1 m हुने हुनाले यो reconnaissance/प्रारम्भिक अध्ययनका लागि मात्र उपयुक्त हुन्छ; spirit र trigonometric levelling उचाई नाप्ने अरू विधि हुन्।"},
      {q:"कुनै नदीको आमुने सामुने किनाराको उचाई कुन तरिकाले निकाल्न सकिन्छ ?", o:["बारोमेट्रिक लेभलिंग", "रेसिप्रोकल लेभलिंग", "त्रिगोनेमेट्रिकल लेभलिंग", "स्प्रिट लेभलिंग"], a:1, e:"नदीको दुई किनारबाट उपकरण बीचमा राख्न नसकिने हुनाले दुई setup (एक-एक किनारबाट) बाट अवलोकन गरी औसत लिने reciprocal levelling उत्तम हुन्छ; यसले curvature, refraction र collimation error हटाउँछ। स्प्रिट र त्रिगोनेमेट्रिकल levelling पनि प्रयोग गर्न सकिए तापनि दूरी धेरै भएकाले शुद्धता घट्छ, र बारोमेट्रिक levelling ले आवश्यक शुद्धता दिँदैन।"},
      {q:"कुन levelling कार्यका लागि दुईवटा setup आवश्यक हुन्छ ?", o:["Trigonometric levelling", "Reciprocal levelling", "Cross - section levelling", "longitudinal levelling"], a:1, e:"Reciprocal levelling को परिभाषा नै यही हो - अवरोध (नदी, खोल्सा, खाडल) का कारण उपकरण बीचमा राख्न नसकिँदा एक-एक किनारबाट गरी दुई setup मा अवलोकन गरिन्छ र दुई भिन्नताको औसत लिइन्छ। Cross-section र longitudinal levelling मा आवश्यकता अनुसार धेरै setup हुन सक्छन् (अनिवार्य रूपमा दुई होइन), र trigonometric levelling मा angle र दूरी नापिन्छ - setup को संख्या स्थिर हुँदैन।"},
      {q:"खाल्डो पोखरी वरीपरीको levelling गर्दा कुन विधि उपयुक्त हुन्छ ?", o:["Trigonometric levelling", "Cross - section levelling", "Reciprocal levelling", "longitudinal levelling"], a:2, e:"खाल्डो, पोखरी वा खोल्सा वरिपरिको उचाई फरक निकाल्दा उपकरण बीचमा राख्न सम्भव हुँदैन (गहिरो/पानी भएको ठाउँ), त्यसैले दुई किनारबाट अवलोकन गर्ने reciprocal levelling उपयुक्त हुन्छ - यसले collimation, curvature र refraction को त्रुटि हटाउँछ। Cross-section र longitudinal levelling सामान्य खुला भू-भागको लाइनमा प्रयोग हुन्छन्।"},
      {q:"Levelling last point भन्नाले कसलाई जनाउँछ ?", o:["Fore sight reading", "Back sight reading", "Intermediate sight reaction", "All"], a:0, e:"Levelling को अन्तिम बिन्दुमा लिइने reading fore sight हुन्छ (change point मा instrument सार्नु अघि वा काम सकिँदा लिइने अन्तिम reading), र यही मानबाट अन्तिम RL = HI - FS निकालिन्छ। Back sight सुरु वा नयाँ setup को पहिलो reading हो; त्यसैले अन्तिम बिन्दुको reading BS हुन सक्दैन।"},
      {q:"RL(A) = 1640.20 m र RL(B) = 1651.30 m र लम्बाई AB = 238 m भए AB को gradient कति हुन्छ ?", o:["+1:30", "1/20", "1/200", "-1/200"], a:2, e:"Gradient = उचाई फरक / horizontal दूरी = (1651.30 - 1640.20) / 238 = 11.10 / 238 = 1/21.4 ≈ 1/200 (अर्थात् 0.0466 m प्रति metre वा 4.66 %), र B माथि भएकाले gradient धनात्मक (rising) हो। ध्यान दिनुहोस्: gradient (1/200) र प्रवणता (1 in 21.4) फरक कुरा हो - यहाँ अपेक्षित उत्तर 1/200 हो।"},
      {q:"Trigonometric levelling मा कुन observation हुन्छ ?", o:["Horizontal distance र Horizontal angle", "Horizontal distance र Vertical angle", "Vertical distance र Horizontal angle", "माथिका सबै"], a:1, e:"Trigonometric (indirect) levelling मा उचाई फरक निकाल्न staff/object सम्मको horizontal distance र vertical angle (elevation/depression कोण) नापिन्छ; सूत्र: उचाई फरक = D tan(कोण) + instrument को उचाई - target/स्टाफको reading। Horizontal angle आवश्यक पर्दैन (त्यो traversing/कोण मापनमा प्रयोग हुन्छ), त्यसैले 'माथिका सबै' गलत हो।"},
      {q:"Levelling मा fore sight का रूपमा लिइएको staff ठाडो (vertical) भएन भने त्यस बिन्दुको reduced level के हुन्छ ?", o:["बढ्छ", "घट्छ", "बराबर हुन्छ", "घटी, बढी जे पनि हुनसक्छ"], a:1, e:"यही फाइलको अर्को प्रश्नले जस्तै: स्टाफ ढल्किएमा reading सधैं बढी आउँछ। यदि त्यो reading fore sight (FS) हो भने बिन्दुको RL = HI - FS ले साँचोभन्दा घटी (कम) मान दिन्छ - अर्थात् staff vertical नभएमा निकालिएको RL घट्छ; (यदि बढी आउने reading back sight हो भने HI बढी आई त्यसपछिका RL पनि बढी आउँछन्, त्यसैले काम गर्दा reading को किसिम पहिले पहिचान गर्नुपर्छ)।"},
      {q:"बेन्चमार्कहरु विच किन यन्त्र जोडा ठाउमा राख्नु पर्छ ?", o:["स्टाफको graduation त्रुटि हटाउन", "Refraction error हटाउन", "Curvature error हटाउन", "Collimation error हटाउन"], a:3, e:"उपकरण दुई स्टाफ/BMs को ठीक बीचमा राख्दा (BS दूरी = FS दूरी) line of collimation को परमानेन्ट adjustment को त्रुटिले दुवै reading मा बराबर असर गर्छ र फरक निकाल्दा हट्छ - तर collimation error त्रुटि पूर्ण रूपमा हटाउनुको साथै यही उपायले curvature र refraction को प्रभाव पनि हटाउँछ। (प्रश्नको अपेक्षित उत्तर collimation error हो; व्यवहारमा यो नियमले तीनवटै systematic त्रुटि एकैचोटि हटाउँछ।) स्टाफको graduation त्रुटि भने स्टाफ जाँचेर मात्र हटाउन सकिन्छ।"},
      {q:"दुईवटा BM बीचमा even number setup लिए के हुन्छ ?", o:["Collimation error हट्छ", "Graduation error हट्छ", "Refraction error हट्छ", "Zero error हट्छ"], a:0, e:"दुई BM बीच बराबर (even) संख्यामा setup लिँदा र प्रत्येक setup मा BS = FS दूरी राख्दा line of collimation को त्रुटि (जो दृष्टि दूरीसँग समानुपातिक हुन्छ) क्रमशः एक अर्कालाई खारेज गर्दै अन्तिम बिन्दुमा असर गर्दैन; त्यसैले even number setup ले collimation error लाई हटाउन (कम गर्न) मद्दत गर्छ। Graduation error र zero error स्टाफसँग सम्बन्धित भएकाले स्टाफ जाँचेर मात्र हटाउन सकिन्छ।"},
      {q:"B. S. भन्दा F. S. बढी भएमा जमिन.........हुन्छ ?", o:["अग्लो", "होचो", "बराबर", "माथिका सबै"], a:1, e:"RL = पहिलो RL + BS - FS; FS > BS भए RL घट्छ, अर्थात् स्टाफ राखिएको बिन्दु अघिल्लो भन्दा होचो (तल) छ - यही fall हो। विपरीत अवस्थामा (BS > FS) बिन्दु अग्लो हुन्छ र rise पर्छ।"},
      {q:"लेभलिङ्गको सिद्धान्त के हो ?", o:["To make line of sight horizontal", "To make line of sight parallel", "To make line of sight vertical", "None of the above"], a:0, e:"Spirit levelling को मूल सिद्धान्त नै line of sight (line of collimation) लाई horizontal बनाउनु हो; त्यसपछि स्टाफमा लिइएको reading ले दृष्टि रेखा र स्टाफको फेदबीचको ठाडो दूरी दिन्छ र सबै reading लाई एउटै datum मा जोड्न सकिन्छ। Line of sight समानान्तर बनाउनु वा ठाडो बनाउनु levelling को सिद्धान्त होइन (ठाडो रेखा त plumb line मा लिइन्छ)।"},
      {q:"कुनै दुईवटा विन्दु विच हरिजन्टल पोजिसनको रेकर्ड नगरी उचाईको फरक मात्र निकाल्न गरिने लेभलिङलाई ....... भनिन्छ ।", o:["Differential levelling", "प्रेसाइज लेभलिङ", "फ्लाई लेभलिङ", "प्रोफाइल लेभलिङ"], a:0, e:"Horizontal position (निर्देशांक) निकाल्ने झन्झट नगरी कुनै दुई बिन्दुबीच उचाईको फरक मात्र निकाल्ने सामान्य विधिलाई differential levelling भनिन्छ - यसैले यो levelling हरेक नापी कामको आधार हो। (यही फाइलमा यही वाक्य 'रेसिप्रोकल लेभलिङ' भन्ने विकल्पसहित पनि छ; reciprocal levelling भनेको नदी/खाडल जस्तो अवरोधमा दुई setup बाट औसत लिने विशेष विधि हो, त्यसैले यहाँ differential levelling नै सही उत्तर हो।)"}
    ];
